INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4554399', 'Battle of Hebron', 'The Battle of Hebron occurred in early August 1834, when the forces of Ibrahim Pasha of Egypt launched an assault against Hebron to crush the last pocket of significant resistance in Palestine during the Peasants'' revolt in Palestine. After heavy street battles, the Egyptian army defeated the rebels of Hebron, and afterward subjected its inhabitants to violence following the fall of the city.', 1834, 7, 24, NULL, NULL, NULL, 'day', '24 July 1834', 37, 'https://en.wikipedia.org/wiki/Battle_of_Hebron'),
  ('Q107600580', 'Malaria in Mandatory Palestine', 'Malaria was a major issue in Mandatory Palestine, having been attested as endemic to the region since the biblical period. In the early 20th century, multiple malaria epidemics resulted in widespread deaths.', 1900, NULL, NULL, 1926, NULL, NULL, 'year', '1900–1926', 30, 'https://en.wikipedia.org/wiki/Malaria_in_Mandatory_Palestine'),
  ('Q7645304', 'Surafend affair', 'The Surafend massacre (Arabic: مجزرة صرفند) was a premeditated massacre committed against inhabitants of the village of Sarafand al-Amar (modern-day Tzrifin) and a Bedouin camp in Ottoman Palestine by occupying Australian, New Zealand and Scottish soldiers on 10 December 1918. The massacre occurred after the Sinai and Palestine campaign of World War I, Allied occupational forces in the region, in particular Australian and New Zealand troops, grew frustrated over being subject to petty theft and an alleged murder by local Arabs without redress.', 1918, 12, 10, NULL, NULL, NULL, 'day', '10 December 1918', 39, 'https://en.wikipedia.org/wiki/Surafend_massacre'),
  ('Q15977823', 'Paulet-Newcombe Agreement', 'The Paulet–Newcombe Agreement or Paulet-Newcombe Line, was a 1923 agreement between the British and French governments regarding the position and nature of the boundary between the British Mandates of Palestine and Iraq, on one side and the French Mandate of Syria and Lebanon. The 1923 line defined the border of Mandatory Palestine from the Mediterranean up to Al-Hamma, Tiberias.', 1923, 7, 3, NULL, NULL, NULL, 'day', '3 July 1923', 41, 'https://en.wikipedia.org/wiki/Paulet%E2%80%93Newcombe_Agreement'),
  ('Q1929123', 'Hadassah medical convoy massacre', 'The Hadassah convoy massacre took place on April 13, 1948, when a convoy, escorted by Haganah militia, bringing medical and military supplies and personnel to Hadassah Hospital on Mount Scopus, Jerusalem, was ambushed by Arab forces. Seventy-eight Jewish doctors, nurses, students, patients, faculty members and Haganah fighters, and one British soldier were killed in the attack, including twenty three women.', 1948, 4, 13, NULL, NULL, NULL, 'day', '13 April 1948', 52, 'https://en.wikipedia.org/wiki/Hadassah_medical_convoy_massacre'),
  ('Q3297456', 'Safsaf massacre', 'The Safsaf massacre took place on 29 October 1948, following the capture of the Palestinian Arab village of Safsaf in the Galilee by the Israel Defense Forces (IDF). The village was defended by the Arab Liberation Army''s Second Yarmuk Battalion.', 1948, 10, 29, NULL, NULL, NULL, 'day', '29 October 1948', 45, 'https://en.wikipedia.org/wiki/Safsaf_massacre'),
  ('Q124053926', 'Abu Shusha massacre', 'The Abu Shusha massacre took place on 13–14 May 1948 during Operation Barak, when the Zionist Givati Brigade mortared and then stormed Abu Shusha, in Mandatory Palestine, killing between 60 and 70+ Palestinian Arab villagers.', 1948, 5, 14, NULL, NULL, NULL, 'day', '14 May 1948', 37, 'https://en.wikipedia.org/wiki/Abu_Shusha_massacre'),
  ('Q4872154', 'Battle of Rafah', 'The Battle of Rafah was a military engagement between the Israel Defense Forces and the Egyptian Army in the final stage of the 1948 Arab–Israeli War. It was fought on January 3–8, 1949, just south of Rafah, today in the Gaza Strip.', 1949, 1, 3, 1949, 1, 8, 'day', '3 January 1949 – 8 January 1949', 34, 'https://en.wikipedia.org/wiki/Battle_of_Rafah_(1949)'),
  ('Q4567412', '1952 raid on Beit Jala', 'The 1952 raid on Beit Jala was a part of the reprisal operations that were carried out by Israel in response to Arab fedayeen attacks from across the Green Line. It involved an Israeli incursion into Beit Jala, a town in the Jordanian-annexed West Bank (now a part of the Palestinian territories), on 6 January 1952, after which three houses were rigged with explosives and subsequently blown up; the attack killed seven civilian residents.', 1952, NULL, NULL, 1953, NULL, NULL, 'year', '1952–1953', 26, 'https://en.wikipedia.org/wiki/1952_raid_on_Beit_Jala'),
  ('Q1139615', 'Qibya massacre', 'The Qibya massacre occurred during Operation Shoshana, an Israeli reprisal operation that occurred in October 1953, when IDF''s Unit 101 led by future Israeli prime minister Ariel Sharon attacked the village of Qibya in the West Bank, which was then under Jordanian control, and killed more than 69 Palestinian civilians, two-thirds of whom were women and children. Forty-five houses, a school, and a mosque were destroyed.', 1953, 10, 15, NULL, NULL, NULL, 'day', '15 October 1953', 58, 'https://en.wikipedia.org/wiki/Qibya_massacre'),
  ('Q2705622', 'Kiryat Shmona massacre', 'The Kiryat Shmona massacre was an attack by three members of the Popular Front for the Liberation of Palestine - General Command on civilians in Kiryat Shmona, Israel during the Jewish holiday of Passover on 11 April 1974. Eighteen people were killed, 8 of them children, and 16 people were wounded.', 1974, 4, 11, NULL, NULL, NULL, 'day', '11 April 1974', 53, 'https://en.wikipedia.org/wiki/Kiryat_Shmona_massacre'),
  ('Q671297', '1983 West Bank fainting epidemic', 'In late March and early April 1983, large numbers of Palestinians in the West Bank complained of fainting and dizziness, the vast majority of whom were teenage schoolgirls and a smaller number of whom were female Israeli soldiers. The symptoms led to 943 hospitalizations.', 1983, 3, 21, 1983, 4, NULL, 'day', '21 March 1983 – April 1983', 37, 'https://en.wikipedia.org/wiki/1983_West_Bank_fainting_epidemic'),
  ('Q1816561', 'Palestinian Declaration of Independence', 'The Palestinian Declaration of Independence formally established the State of Palestine, and was written by Palestinian poet Mahmoud Darwish and proclaimed by Yasser Arafat on 15 November 1988 (5 Rabiʽ al-Thani 1409) in Algiers, Algeria. It had previously been adopted by the Palestinian National Council (PNC), the legislative body of the Palestine Liberation Organization (PLO), by a vote of 253 in favour, 46 against, and 10 abstaining.', 1988, 11, 15, NULL, NULL, NULL, 'day', '15 November 1988', 64, 'https://en.wikipedia.org/wiki/Palestinian_Declaration_of_Independence'),
  ('Q2896635', 'Battle of Nablus', 'The Battle of Nablus was fought from April 5 to April 8, 2002, in the Palestinian city of Nablus in the West Bank between the Israel Defense Forces (IDF) and Palestinian forces, as part of Operation Defensive Shield in the Second Intifada. It resulted in an Israeli victory.', 2002, NULL, NULL, 2002, 4, 8, 'year', '2002', 39, 'https://en.wikipedia.org/wiki/Battle_of_Nablus'),
  ('Q4871330', 'Battle of Jenin', 'The Battle of Jenin, took place in the Jenin refugee camp in the Israeli-occupied West Bank on April 1–11, 2002. The Israeli military invaded the camp, and other areas under the administration of the Palestinian Authority, during the Second Intifada, as part of Operation Defensive Shield.', 2002, NULL, NULL, NULL, NULL, NULL, 'year', '2002', 50, 'https://en.wikipedia.org/wiki/Battle_of_Jenin_(2002)'),
  ('Q123139694', 'killing of Ahmed Yassin', 'On 22 March 2004, the Palestinian leader and one of the founders of Hamas, Ahmed Yassin, aged 67, was assassinated in Gaza City. Sheikh Ahmed Yassin – who used a wheelchair due to being quadriplegic since his adolescence – was returning from performing the Fajr prayer, and his companions were also killed immediately.', 2004, 3, 22, NULL, NULL, NULL, 'day', '22 March 2004', 41, 'https://en.wikipedia.org/wiki/Killing_of_Ahmed_Yassin'),
  ('Q373655', 'Battle of Gaza (2007)', 'The Battle of Gaza, also known as the Gaza Civil War, was a brief civil war between Fatah and Hamas that took place in the Gaza Strip from 7 to 15 June 2007. It was a prominent event in the Fatah–Hamas conflict, centered on the struggle for power after the fall of the National Unity Government between Hamas and Fatah, which was dissolved shortly afterwards.', 2007, 6, 10, 2007, 6, 15, 'day', '10 June 2007 – 15 June 2007', 62, 'https://en.wikipedia.org/wiki/Battle_of_Gaza_(2007)'),
  ('Q170682', 'Gaza War (2008–2009)', 'The Gaza War, also known as the First Gaza War, Operation Cast Lead, or the Gaza Massacre, and referred to as the Battle of al-Furqan by Hamas, was a three-week armed conflict between Gaza Strip Palestinian paramilitary groups and the Israel Defense Forces (IDF) that began on 27 December 2008 and ended on 18 January 2009 with a unilateral ceasefire. The conflict resulted in 1,166–1,417 Palestinian and 13 Israeli deaths.', 2008, 12, 27, 2009, 1, 18, 'day', '27 December 2008 – 18 January 2009', 78, 'https://en.wikipedia.org/wiki/Gaza_War_(2008%E2%80%932009)'),
  ('Q5644118', 'Battle of Rafah', 'The Battle of Rafah (2009) took place between Hamas and Jund Ansar Allah in the Rafah Governorate of the Gaza Strip. Fighting between the two Palestinian militant organizations broke out on 14 August 2009, when Jund Ansar Allah''s founder Abdel Latif Moussa denounced the Hamas government for supposedly failing to enforce Islamic law and for "not being any different from a secular government" since it ousted Fatah during the Battle of the Gaza Strip in June 2007.', 2009, 8, 14, 2009, 8, 15, 'day', '14 August 2009 – 15 August 2009', 37, 'https://en.wikipedia.org/wiki/Battle_of_Rafah_(2009)'),
  ('Q4702325', 'Al-Dalu family killing', 'The Al-Dalu family killing occurred when twelve people were killed in an Israeli airstrike in the Gaza Strip on 18 November 2012, during the 2012 Gaza war. Ten members of the al-Dalu family were killed, including five children and an elderly woman, plus of two of the family''s neighbors including another elderly woman.', 2012, 11, NULL, NULL, NULL, NULL, 'month', 'November 2012', 34, 'https://en.wikipedia.org/wiki/Al-Dalu_family_killing'),
  ('Q17387592', 'Battle of Shuja''iyya (2014)', 'The Battle of Shuja''iyya occurred between the Israel Defense Forces and the Izz ad-Din al-Qassam Brigades on 20 July 2014 during 2014 Israel–Gaza conflict in the Shuja''iyya neighborhood of Gaza City, in the Gaza Strip. Shuja''iyya, with 92,000 people in 6 sq-kilometres, is one of the most densely populated areas of the Gaza Strip.', 2014, 7, NULL, 2014, 7, 23, 'month', 'July 2014 – 23 July 2014', 39, 'https://en.wikipedia.org/wiki/Battle_of_Shuja''iyya_(2014)'),
  ('Q123914052', 'Black Friday', 'Black Friday refers to a series of military strikes that took place in Rafah, a city in the southern Gaza Strip, over a period of four days starting on 1 August 2014. The events are notable for their intensity and the high number of casualties, particularly within the context of the larger conflict known as the 2014 Israel–Gaza conflict or Operation Protective Edge.', 2014, 8, 1, NULL, NULL, NULL, 'day', '1 August 2014', 34, 'https://en.wikipedia.org/wiki/Black_Friday_(bombing_campaign)'),
  ('Q51139646', '2018–2019 Gaza border protests', 'The 2018–2019 Gaza border protests, also known as the Great March of Return (Arabic: مسیرة العودة الكبرى, romanized: Masīra al-ʿawda al-kubrā), were a series of demonstrations held each Friday in the Gaza Strip near the Gaza–Israel barrier from 30 March 2018 until 27 December 2019, in which Israel killed a total of 223 Palestinians. The demonstrators demanded that the Palestinian refugees must be allowed to return to lands they were displaced from in territory that was Mandatory Palestine and is now Israel.', 2018, 3, 30, NULL, NULL, NULL, 'day', '30 March 2018', 67, 'https://en.wikipedia.org/wiki/2018%E2%80%932019_Gaza_border_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q122962941', 'Gaza War', 'The Gaza war is an armed conflict in the Gaza Strip and Israel, fought as part of the unresolved Israeli–Palestinian and Gaza–Israel conflicts. The war began on 7 October 2023, when Palestinian militant group Hamas led an attack on Israel, in which 1,195 Israelis and foreign nationals were killed and 251 were taken hostage.', 2020, NULL, NULL, NULL, NULL, NULL, 'decade', '2020s', 91, 'https://en.wikipedia.org/wiki/Gaza_war'),
  ('Q123550499', 'attacks on health facilities during the Gaza war', 'A significant number of attacks on healthcare facilities occurred during the Gaza war and genocide. During the first week of the war, there were 94 attacks on health care facilities in Israel and Gaza, killing 29 healthcare workers and injuring 24.', 2020, NULL, NULL, NULL, NULL, NULL, 'decade', '2020s', 41, 'https://en.wikipedia.org/wiki/Attacks_on_health_facilities_during_the_Gaza_war'),
  ('Q106786309', 'Operation Guardian of the Walls', 'A major outbreak of violence in the Israeli–Palestinian conflict, sometimes called the Unity Intifada, mainly commenced on 10 May 2021 and continued until a ceasefire came into effect on 21 May. It was marked by protests and police riot control, rocket attacks on Israel by Hamas and Palestinian Islamic Jihad (PIJ), and Israeli airstrikes in the Gaza Strip.', 2021, 5, NULL, 2021, 5, 21, 'month', 'May 2021 – 21 May 2021', 45, 'https://en.wikipedia.org/wiki/Operation_Guardian_of_the_Walls'),
  ('Q111606488', '2022 Al-Aqsa Mosque storming', 'On 15 April 2022, clashes erupted between Palestinians and Israeli Security Forces on the Al-Aqsa compound in the Old City of Jerusalem. According to the United Nations Special Coordinator for the Middle East Peace Process, the clashes began when Palestinians threw stones, firecrackers, and other heavy objects at Israeli police officers.', 2022, 4, 15, NULL, NULL, NULL, 'day', '15 April 2022', 53, 'https://en.wikipedia.org/wiki/2022_Al-Aqsa_clashes'),
  ('Q111968653', 'killing of Shireen Abu Akleh', 'On 11 May 2022, Palestinian-American journalist Shireen Abu Akleh was shot and killed by Israel Defense Forces while covering a raid at the Jenin refugee camp. Witnesses, along with the Qatari media network Al Jazeera, for which Abu Akleh had worked for 25 years, reported that an Israeli soldier shot her in the head.', 2022, 5, 11, NULL, NULL, NULL, 'day', '11 May 2022', 34, 'https://en.wikipedia.org/wiki/Killing_of_Shireen_Abu_Akleh'),
  ('Q123109101', 'al-Ahli Arab Hospital explosion', 'On 17 October 2023, an explosion took place in a courtyard of al-Ahli Arab Hospital in Gaza City during the Gaza war, resulting in a large number of displaced Palestinians seeking shelter there being killed or injured. International media initially reported that over 500 Palestinians were killed according to the Gaza Health Ministry (GHM), but this was a mistranslation of a report that had mentioned over 500 total victims, including injured.', 2023, 10, 17, NULL, NULL, NULL, 'day', '17 October 2023', 64, 'https://en.wikipedia.org/wiki/Al-Ahli_Arab_Hospital_explosion'),
  ('Q123290408', 'Siege of Gaza City', 'The siege of Gaza City was an engagement of the Gaza war that began on 2 November 2023, when the Israel Defense Forces (IDF) surrounded Gaza City, amid the Israeli invasion of the Gaza Strip after the October 7 attacks. Gaza City is the most populated city in the Gaza Strip and the battle started on 30 October 2023, when Israel and Hamas clashed in Gaza City.', 2023, 11, NULL, NULL, NULL, NULL, 'month', 'November 2023', 39, 'https://en.wikipedia.org/wiki/Siege_of_Gaza_City'),
  ('Q123314553', 'Al-Shifa ambulance airstrike', 'A significant number of attacks on healthcare facilities occurred during the Gaza war and genocide. During the first week of the war, there were 94 attacks on health care facilities in Israel and Gaza, killing 29 healthcare workers and injuring 24.', 2023, 11, 3, NULL, NULL, NULL, 'day', '3 November 2023', 37, 'https://en.wikipedia.org/wiki/Al-Shifa_ambulance_airstrike'),
  ('Q123369926', 'Battle of Beit Hanoun', 'The battle of Beit Hanoun began on 27 October 2023 at the start of the Israeli invasion of the Gaza Strip. On 18 December 2023, Israeli forces had prematurely signalled that they had full control over Beit Hanoun and had destroyed Hamas'' Beit Hanoun Battalion.', 2023, NULL, NULL, 2025, 5, 16, 'year', '2023 – 16 May 2025', 41, 'https://en.wikipedia.org/wiki/Battle_of_Beit_Hanoun'),
  ('Q123422121', 'Al-Shifa Hospital Siege', 'Al-Shifa Hospital, the largest medical complex in Gaza, was placed under siege by Israel in mid-November 2023 during the Gaza war, after saying it had contained a Hamas command and control center beneath it. The incident was followed by a second major raid by Israeli forces in March 2024.', 2023, 11, NULL, 2024, 4, 1, 'month', 'November 2023 – 1 April 2024', 45, 'https://en.wikipedia.org/wiki/Al-Shifa_Hospital_siege'),
  ('Q123697491', 'Siege of Khan Yunis', 'The battle of Khan Yunis, which evolved into the siege of Khan Yunis in late January 2024, began on 1 December 2023 in the midst of the Israeli invasion of the Gaza Strip.', 2023, 12, 1, NULL, NULL, NULL, 'day', '1 December 2023', 39, 'https://en.wikipedia.org/wiki/Siege_of_Khan_Yunis'),
  ('Q124086054', 'Gaza genocide', 'The Gaza genocide is the ongoing, intentional, and systematic destruction of the Palestinian people in the Gaza Strip carried out by Israel during the Gaza war. It encompasses mass killings, including the targeted killing of children (who account for 30% of those killed), deliberate starvation, infliction of serious bodily and mental harm, and prevention of births.', 2023, 10, 7, NULL, NULL, NULL, 'day', '7 October 2023', 85, 'https://en.wikipedia.org/wiki/Gaza_genocide'),
  ('Q124119981', 'Battle of Jabalia', 'The battle of Jabalia was a battle fought between Israel and Hamas-led Palestinian forces in Jabalia in the Gaza Strip, as part of the ongoing Gaza war. It began on 8 November 2023 as part of the 2023 Israeli invasion of the Gaza Strip, and ended its first phase in late January 2024 with an Israeli withdrawal.', 2023, 10, 26, 2024, 1, 6, 'day', '26 October 2023 – 6 January 2024', 34, 'https://en.wikipedia.org/wiki/Battle_of_Jabalia'),
  ('Q124302798', 'Gaza Strip famine', 'The population of the Gaza Strip underwent a famine as a result of an Israeli blockade during the Gaza war between 22 August 2025 and 19 December 2025. The prevention of basic essentials and humanitarian aid from entering Gaza, as well as airstrikes that destroyed food infrastructure, such as bakeries, mills, and food stores, caused a widespread scarcity of essential supplies.', 2023, 10, NULL, 2026, 1, 5, 'month', 'October 2023 – 5 January 2026', 57, 'https://en.wikipedia.org/wiki/Gaza_Strip_famine'),
  ('Q124477340', 'killing of Hind Rajab', 'Hind Rami Iyad Rajab (Arabic: هند رامي إياد رجب; 3 May 2018 – 29 January 2024) was a five-year-old Palestinian girl in the Gaza Strip who was killed by the Israel Defense Forces (IDF), which also killed six of her family members and two paramedics coming to her rescue, during the Gaza war. On 29 January 2024, Rajab and her family were fleeing Gaza City when their vehicle was shelled by the IDF, killing her uncle, aunt and three cousins, with Rajab and another cousin surviving and contacting the Palestine Red Crescent Society (PRCS) to ask for help while noting that they were being attacked…', 2024, 1, 29, NULL, NULL, NULL, 'day', '29 January 2024', 65, 'https://en.wikipedia.org/wiki/Killing_of_Hind_Rajab'),
  ('Q124546903', 'Nasser Hospital Siege', 'During the Gaza war, the Nasser Hospital faced multiple attacks, including a siege and raid in January and February 2024. The hospital siege by Israeli forces created severe shortages of food, anesthesia, and painkillers.', 2024, 1, 21, NULL, NULL, NULL, 'day', '21 January 2024', 34, 'https://en.wikipedia.org/wiki/Nasser_Hospital_siege'),
  ('Q124695144', 'Flour Massacre', 'The Flour Massacre (Arabic: مجزرة الطحين, romanized: majzarat aṭ-ṭaḥīn) occurred in the Gaza Strip on 29 February 2024, when at least 118 Palestinians were killed and 760 injured after Israeli forces opened fire while the Palestinians were seeking food from aid trucks on the coastal al-Rashid Street in Gaza City. The name Flour Massacre arises from the fact that many victims were found soaked in both flour and blood, symbolizing the humanitarian crisis and the deadly consequences of seeking basic sustenance in a conflict zone.', 2024, 2, 29, NULL, NULL, NULL, 'day', '29 February 2024', 55, 'https://en.wikipedia.org/wiki/Flour_Massacre'),
  ('Q125273168', 'World Central Kitchen drone strikes', 'The World Central Kitchen aid convoy attack occurred on 1 April 2024, when Israeli drones targeted a three-car convoy belonging to World Central Kitchen (WCK) in the Gaza Strip, killing seven aid workers. The workers had been overseeing the transfer of a shipment of food from a makeshift pier to a warehouse some distance away in the northern Gaza Strip, which has been pushed close to famine by Israel''s invasion and blockade during the Gaza war.', 2024, 4, 1, NULL, NULL, NULL, 'day', '1 April 2024', 50, 'https://en.wikipedia.org/wiki/World_Central_Kitchen_aid_convoy_attack'),
  ('Q126140767', 'Tel al-Sultan camp airstrike', 'On 26 May 2024, the Israeli Air Force bombed a displacement camp in Tel al-Sultan, Rafah. The attack, which set the camp on fire, killed between 45 and 50 Palestinians and injured more than 200.', 2024, 5, 26, NULL, NULL, NULL, 'day', '26 May 2024', 48, 'https://en.wikipedia.org/wiki/Tel_al-Sultan_attack'),
  ('Q126389700', 'Al-Sardi school attack', 'On 6 June 2024, the Israel Defense Forces fired two missiles that hit Al-Sardi, a UNRWA school in the Nuseirat refugee camp. Though the complex had not been used as a school since the outbreak of the war, UNRWA said approximately 6,000 people were using it for shelter.', 2024, 6, 6, NULL, NULL, NULL, 'day', '6 June 2024', 41, 'https://en.wikipedia.org/wiki/Al-Sardi_school_attack'),
  ('Q126453114', 'Nuseirat refugee camp massacre', 'On 8 June 2024, the Israel Defense Forces rescued four hostages from the Nuseirat refugee camp, and, during the operation, killed at least 276 Palestinians and injured over 698. Due to the high death toll, some sources have referred to the operation as a massacre, and one of the largest massacres of the Gaza war.', 2024, 6, 8, NULL, NULL, NULL, 'day', '8 June 2024', 39, 'https://en.wikipedia.org/wiki/Nuseirat_refugee_camp_massacre'),
  ('Q126888897', 'June 2024 northern Gaza City airstrikes', 'The June 2024 northern Gaza City airstrikes or the al-Shati and Tuffah dual airstrikes took place on 22 June 2024, when two airstrikes conducted by the Israeli Defense Forces (IDF) occurred at roughly the same time in northern districts of Gaza City, striking the al-Shati refugee camp and the Tuffah district, killing at least 43 people and wounding dozens more.', 2024, 6, 22, NULL, NULL, NULL, 'day', '22 June 2024', 34, 'https://en.wikipedia.org/wiki/June_2024_northern_Gaza_City_airstrikes'),
  ('Q127220552', 'June 2024 Al-Mawasi refugee camp attack', 'On 21 June 2024, Israeli forces attacked refugee tent camps in al-Mawasi, Gaza Strip just outside an area designated as a humanitarian safe zone. The Gaza Health Ministry reported that 25 people were killed and 50 others were injured in the two rounds of bombing.', 2024, 6, 21, NULL, NULL, NULL, 'day', '21 June 2024', 37, 'https://en.wikipedia.org/wiki/June_2024_Al-Mawasi_refugee_camp_attack'),
  ('Q127302766', 'Al-Awda School massacre', 'On 9 July 2024, the Israel Defense Forces bombed Al-Awda school – the UNRWA-run school that had been converted into a displacement shelter, hosting refugees from the Israeli invasion – in Abasan al-Kabira near the city of Khan Yunis, in the Gaza Strip, Palestine. At least 31 Palestinians were killed in the attack while over 53 were injured; most of the casualties were women and children.', 2024, 7, 9, NULL, NULL, NULL, 'day', '9 July 2024', 41, 'https://en.wikipedia.org/wiki/Al-Awda_school_attack'),
  ('Q127420299', 'July 2024 al-Mawasi attack', 'On 13 July 2024, Israeli airstrikes hit the Al-Mawasi area near Khan Yunis in the Gaza Strip during the Gaza war. The attack killed at least 90 Palestinians, among them women and children, and injured over 300.', 2024, 7, 13, NULL, NULL, NULL, 'day', '13 July 2024', 43, 'https://en.wikipedia.org/wiki/13_July_2024_al-Mawasi_attack'),
  ('Q127597969', 'July 2024 al-Shati refugee camp attack', 'On 13 July 2024, the Israel Defense Forces (IDF) conducted an attack against a makeshift mosque in the al-Shati refugee camp in Gaza City. The bombings killed 22 worshippers as they prayed inside the mosque.', 2024, 7, 13, NULL, NULL, NULL, 'day', '13 July 2024', 34, 'https://en.wikipedia.org/wiki/July_2024_al-Shati_refugee_camp_attack'),
  ('Q128799073', 'Al-Tabaeen school attack', 'On 10 August 2024, Israel struck the Al-Tabaeen school located in eastern Gaza City, which was hosting displaced Palestinians seeking shelter there during the Gaza war. According to Palestinian health authorities, at least 80 Palestinians were killed and 47 others were injured, with several victims being trapped in the school as the fire spread.', 2024, 8, 10, NULL, NULL, NULL, 'day', '10 August 2024', 39, 'https://en.wikipedia.org/wiki/Al-Tabaeen_school_attack'),
  ('Q128810352', 'Hamama School bombing', 'On 4 August 2024, the Israel Defense Forces (IDF) bombed Hamama School in the neighborhood of Sheikh Radwan, Gaza City. The school had been sheltering people displaced by the Israeli invasion of the Gaza Strip, including women and children.', 2024, 8, 4, NULL, NULL, NULL, 'day', '4 August 2024', 37, 'https://en.wikipedia.org/wiki/Hamama_School_bombing'),
  ('Q129559774', 'Khadija School airstrike', 'The Khadija School airstrike by the Israel Defense Forces (IDF) occurred on 26 July 2024 during the Gaza war in the central region of Gaza, specifically in Deir al-Balah. The airstrike killed at least 30 individuals, including seven minors.', 2024, 7, 27, NULL, NULL, NULL, 'day', '27 July 2024', 37, 'https://en.wikipedia.org/wiki/Khadija_School_airstrike'),
  ('Q130301591', 'September 2024 Al-Jawni School attack', 'On 11 September 2024, the Israel Defense Forces bombed the UN-run Al-Jawni school in the Nuseirat refugee camp of central Gaza. The school had been sheltering people displaced by the Israeli invasion of the Gaza Strip, including women and children.', 2024, 9, 11, NULL, NULL, NULL, 'day', '11 September 2024', 37, 'https://en.wikipedia.org/wiki/2024_Al-Jawni_School_attack'),
  ('Q135114453', 'anti-Hamas insurgency in the Gaza Strip', 'The anti-Hamas insurgency in the Gaza Strip is an ongoing insurgency in the Gaza Strip that began in May 2024. It involves clashes between the Hamas-led government and the anti-Hamas militant groups in Gaza, some of which are backed by Israel''s Mossad and affiliated with Fatah.', 2024, 9, NULL, NULL, NULL, NULL, 'month', 'September 2024', 37, 'https://en.wikipedia.org/wiki/Anti-Hamas_insurgency_in_the_Gaza_Strip'),
  ('Q133818618', 'March 2025 Rafah humanitarian convoy attacks', 'On 23 March 2025, the Israel Defense Forces (IDF) attacked several humanitarian vehicles, including five ambulances, a fire truck, and a United Nations vehicle, in Al-Hashashin area in southern Rafah, Gaza Strip. The massacre resulted in the deaths of 15 aid workers, including eight members of the Palestine Red Crescent Society, five civil defense, and one UN agency employee.', 2025, 3, 23, NULL, NULL, NULL, 'day', '23 March 2025', 45, 'https://en.wikipedia.org/wiki/Rafah_paramedic_massacre'),
  ('Q134459908', '2025 Gaza European Hospital strike', 'On 13 May 2025, Israeli airstrikes hit the compound of the Gaza European Hospital in Khan Yunis, Gaza Strip, and the surrounding area, killing Hamas leader Mohammed Sinwar, Rafah Brigade commander Muhammad Shabana and 20+ others. At least 40 more people were injured.', 2025, 5, 13, NULL, NULL, NULL, 'day', '13 May 2025', 39, 'https://en.wikipedia.org/wiki/2025_Gaza_European_Hospital_strikes'),
  ('Q134596372', 'Fahmi al-Jarjawi School Massacre', 'On 25 May 2025, the Israel Defense Forces (IDF) targeted the Fahmi al-Jarjawi School in Daraj, Gaza City, killing at least 36 people and wounding 55 others, including 18 children and six women. The attack occurred in the midst of mounting international criticism of Israel''s conduct in the Gaza war.', 2025, 5, 25, NULL, NULL, NULL, 'day', '25 May 2025', 34, 'https://en.wikipedia.org/wiki/Fahmi_al-Jarjawi_School_attack'),
  ('Q135208548', 'Al-Baqa Cafe airstrike', 'On 30 June 2025, the Israel Defense Forces (IDF) conducted an airstrike on the al-Baqa internet café near the port of Gaza City, within the Gaza Strip. The attack killed at least 41 people—including photojournalist Ismail Abu Hatab—and injured another 75.', 2025, 6, 30, NULL, NULL, NULL, 'day', '30 June 2025', 37, 'https://en.wikipedia.org/wiki/Al-Baqa_Caf%C3%A9_airstrike');
